AutostartOptions = S.Struct({
  timeoutMs: S.optional(S.Finite),
  pollIntervalMs: S.optional(S.Finite),
  platform: S.optional(S.String),
})

ReadDescriptorResult = S.Union([
  S.Struct({
    ok: S.Literal(true).pipe(S.mutableKey),
    descriptor: DescriptorPayload.pipe(S.mutableKey),
    path: S.String.pipe(S.mutableKey),
  }),
  S.Struct({
    ok: S.Literal(false).pipe(S.mutableKey),
    envelope: ErrorEnvelope.pipe(S.mutableKey),
    path: S.String.pipe(S.mutableKey),
  }),
])

ResolveDescriptorOptions = S.Struct({
  pathOverride: S.optional(S.String).pipe(S.mutableKey),
  envOverride: S.String.pipe(S.NullOr, S.optional, S.mutableKey),
  platform: S.optional(S.String).pipe(S.mutableKey),
  homeDirectory: S.optional(S.String).pipe(S.mutableKey),
})

DownloadDetachedEnvelope = S.Struct({
  ok: S.Literal(true).pipe(S.mutableKey),
  mode: S.Literal("download").pipe(S.mutableKey),
  task: S.Struct({
    id: S.Unknown.pipe(S.mutableKey),
    status: S.Unknown.pipe(S.mutableKey),
    attempt: S.Unknown.pipe(S.mutableKey),
    maxAttempts: S.Unknown.pipe(S.mutableKey),
    command: S.String.pipe(S.mutableKey),
  }).pipe(S.mutableKey),
})

DownloadWaitFailureEnvelope = S.Struct({
  ok: S.Literal(false).pipe(S.mutableKey),
  mode: S.Literal("download").pipe(S.mutableKey),
  task: S.Unknown.pipe(S.mutableKey),
  ytDlp: WaitOutput.pipe(S.mutableKey),
})

DownloadWaitSuccessEnvelope = S.Struct({
  ok: S.Literal(true).pipe(S.mutableKey),
  mode: S.Literal("download").pipe(S.mutableKey),
  task: S.Unknown.pipe(S.mutableKey),
  ytDlp: WaitOutput.pipe(S.mutableKey),
})

ErrorEnvelope = S.Struct({
  ok: S.Literal(false).pipe(S.mutableKey),
  code: ErrorCode.pipe(S.mutableKey),
  message: S.String.pipe(S.mutableKey),
  details: S.optional(S.Record(S.String, S.Unknown.pipe(S.mutableKey))).pipe(S.mutableKey),
})

ProbeOutput = S.Struct({
  exitCode: S.Finite.pipe(S.mutableKey),
  stdout: S.String.pipe(S.mutableKey),
  stderr: S.String.pipe(S.mutableKey),
})

ProbeSuccessEnvelope = S.Struct({
  ok: S.Literal(true).pipe(S.mutableKey),
  mode: S.Literal("probe").pipe(S.mutableKey),
  command: S.String.pipe(S.mutableKey),
  ytDlp: ProbeOutput.pipe(S.mutableKey),
})

WaitOutput = S.Struct({
  exitCode: S.Finite.pipe(S.mutableKey),
  stdoutTail: S.String.pipe(S.mutableKey),
  stderrTail: S.String.pipe(S.mutableKey),
})

ParsedArgv = S.Union([
  S.Struct({
    kind: S.Literal("subcommand").pipe(S.mutableKey),
    flags: VidbeeFlags.pipe(S.mutableKey),
    subcommand: S.String.pipe(S.mutableKey),
    subArgs: S.Array(S.String).pipe(S.mutableKey),
  }),
  S.Struct({
    kind: S.Literal("ytdlp").pipe(S.mutableKey),
    flags: VidbeeFlags.pipe(S.mutableKey),
    mode: LiteralKit(["probe", "download"]).pipe(S.mutableKey),
    ytArgs: S.Array(S.String).pipe(S.mutableKey),
    probeFlag: S.NullOr(S.String).pipe(S.mutableKey),
  }),
])

ProbeOptions = S.Struct({
  argv: S.Array(S.String).pipe(S.mutableKey),
  ytDlpPath: S.optional(S.String).pipe(S.mutableKey),
  stdoutMaxBytes: S.optional(S.Finite).pipe(S.mutableKey),
  stderrTailBytes: S.optional(S.Finite).pipe(S.mutableKey),
})

ProbeResult = S.Union([
  S.Struct({
    kind: S.Literal("success").pipe(S.mutableKey),
    stdout: S.String.pipe(S.mutableKey),
    stderr: S.String.pipe(S.mutableKey),
    exitCode: S.Finite.pipe(S.mutableKey),
    binary: S.String.pipe(S.mutableKey),
  }),
  S.Struct({ kind: S.Literal("error").pipe(S.mutableKey), envelope: ErrorEnvelope.pipe(S.mutableKey) }),
])

CliVersionInfo = S.Struct({
  cli: S.String.pipe(S.mutableKey),
  contract: S.String.pipe(S.mutableKey),
  changelog: S.String.pipe(S.mutableKey),
})

UpgradeCheckInput = S.Struct({
  current: S.String.pipe(S.mutableKey),
  cachePath: S.optional(S.String).pipe(S.mutableKey),
  force: S.optional(S.Boolean).pipe(S.mutableKey),
})

